import type { ReviewSource } from "./types";

const DATE_FORMAT = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  year: "numeric",
  timeZone: "UTC",
});

/**
 * The demo badge's source line (docs/10). Reviews generated by Claude only count when every
 * review was; a mix, or no reviews yet, is described as written by hand.
 */
export function demoSourceLine(sources: ReviewSource[]): string {
  const generated = sources.filter((s) => s.kind === "claude");
  if (sources.length === 0 || generated.length !== sources.length) {
    return "Sample reviews written by hand";
  }
  const latest = generated
    .map((s) => s.generatedAt)
    .sort()
    .at(-1)!;
  return `Reviews generated by Claude on ${DATE_FORMAT.format(new Date(latest))}`;
}
